    "is_multiple": false,
    "explanation_en": "**Official Justification (Scrum Guide 2020):** **MYTH!** Everyone involved in developing a product benefits from understanding the product vision and Product Goal. It provides shared direction, inspires creative solutions, and aligns decentralized decision-making.",
    "explanation_es": "**Justificación Oficial (Guía Scrum 2020):** **¡Es un MITO!** Todas las personas asociadas al desarrollo de un producto (Developers, Product Owner, Scrum Master y partes interesadas) se benefician profundamente de comprender la visión y el **Objetivo del Producto (Product Goal)**. La visión inspira soluciones creativas, alinea la toma de decisiones descentralizada en entornos complejos y permite que los Developers comprendan el valor de cada incremento."
