    "explanation_en": "**Official Justification (Scrum Guide 2020):** In complex environments, a clear vision acts as a compass, keeps teams focused amidst continuous change, and enables rapid decision-making without prescribing detailed execution.",
    "explanation_es": "**Justificación Oficial (Guía Scrum 2020):** En entornos complejos, el camino detallado no se puede conocer por adelantado. Una visión sólida actúa como **brújula estratégica**, brinda **foco frente a los cambios constantes** y empodera a los equipos para **tomar decisiones ágiles bajo incertidumbre**. Nunca elimina la necesidad de adaptarse ni dicta 'el cómo' (la autogestión técnica corresponde a los Developers)."
